package com.jadhavr.erp.email.service;import com.jadhavr.erp.email.config.MailProperties;import jakarta.mail.internet.MimeMessage;import org.springframework.mail.javamail.*;import org.springframework.stereotype.Component;import java.util.UUID;@Component public class SmtpEmailProvider implements EmailProvider{private final JavaMailSender sender;private final MailProperties p;public SmtpEmailProvider(JavaMailSender s,MailProperties p){sender=s;this.p=p;}public EmailProviderResult send(EmailMessage m){try{MimeMessage mm=sender.createMimeMessage();MimeMessageHelper h=new MimeMessageHelper(mm,true,"UTF-8");h.setFrom(p.getFromAddress(),p.getFromName());h.setReplyTo(p.getReplyTo());h.setTo(m.to());h.setSubject(m.subject());h.setText(m.text(),m.html());sender.send(mm);return new EmailProviderResult(UUID.randomUUID().toString());}catch(Exception e){throw new IllegalStateException("SMTP delivery failed",e);}}}
